struct LongHashCounterL {
    unordered_map<long long, long long> map;
    bool containsKey(long long x) {
        return map.find(x) != map.end();
    }
    long long get(long long x) {
        auto it = map.find(x);
        if (it != map.end()) return it->second;
        return 0;
    }
    long long put(long long x, long long v) {
        long long old = 0;
        auto it = map.find(x);
        if (it != map.end()) {
            old = it->second;
            it->second = v;
        } else {
            map[x] = v;
        }
        return old;
    }
};

