        cachelimit = s;
        this->primes = sieveEratosthenes(s);
        int xcums_size = (s >> 6) + 1;
        xcums.assign(xcums_size, 0);
        isp.assign(xcums_size, 0ULL);
        for (int p : this->primes) isp[p >> 6] |= 1ULL << p;
        for (int i = 0; i < xcums_size - 1; i++)
            xcums[i + 1] = xcums[i] + __builtin_popcountll(isp[i]);

        cumps.resize(M);
        vector<bool> b = {true};
        int len = 1;
        for (int i = 0; i < M; i++) {
            len *= FP[i];
            vector<bool> c(len);
            for (int j = 0; j < FP[i]; j++) {
                copy(b.begin(), b.end(), c.begin() + j * b.size());
            }
            for (int k = 0; k < len; k += FP[i]) c[k] = false;
            cumps[i].resize(len + 1);
            for (int j = 0; j < len; j++)
                cumps[i][j + 1] = cumps[i][j] + (c[j] ? 1 : 0);
            FP[i] = len;
            b = c;
        }
    }

    long long sqrt(long long n) {
        long long i = max(0LL, (long long)std::sqrt(n) - 2);
        while (i * i <= n) i++;
        return i - 1;
    }

    long long cbrt(long long n) {
        long long i = max(0LL, (long long)std::cbrt(n) - 2);
        while (i * i * i <= n) i++;
        return i - 1;
    }

    long long pi(long long x) {
